                        else:
                            date_str = date_part
                        try:
                            datetime.datetime.strptime(date_str, "%Y-%m-%d")
                            holidays.add(date_str)
                        except ValueError:
                            pass
    except FileNotFoundError:
        pass
    _HOLIDAYS = holidays
    return holidays


