def valid_parens(s: str) -> bool:
    """Return True if every (, [, { is closed by the matching bracket in the right order."""
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    openings = set(pairs.values())
    for ch in s:
        if ch in openings:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
        else:
            # ignore other characters
            continue
    return not stack

def merge_intervals(iv: list) -> list:
    """Merge overlapping [start, end] intervals; return them sorted by start. Touching intervals merge."""
    if not iv:
        return []
    # sort by start
    iv_sorted = sorted(iv, key=lambda x: x[0])
    merged = [iv_sorted[0]]
    for curr in iv_sorted[1:]:
        last = merged[-1]
        # if current start <= last end (touching or overlapping)
        if curr[0] <= last[1]:
            # merge
            merged[-1] = [last[0], max(last[1], curr[1])]
        else:
            merged.append(curr)
    return merged

def word_count(text: str) -> dict:
